/* eslint-disable @next/next/no-img-element -- Local QR image generated by the server. */
'use client';
import { useCallback, useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';
import { Button } from '@/components/ui/button';
import { Card, CardBody, CardHeader } from '@/components/ui/card';
import { SitePicker } from '@/components/map/site-picker';
type Checkpoint = { id: string; name: string; latitude: number; longitude: number; radiusM: number; qrVersion: number; active: boolean };
type Policy = { enabled: boolean; minIntervalMinutes: number; maxIntervalMinutes: number; responseMinutes: number };
const presets = [
  { id: 'standard', name: 'Standard · every 15–40 minutes', min: 15, max: 40, response: 10 },
  { id: 'frequent', name: 'Frequent · every 10–20 minutes', min: 10, max: 20, response: 10 },
  { id: 'relaxed', name: 'Less frequent · every 30–60 minutes', min: 30, max: 60, response: 15 },
  { id: 'test', name: 'Short test · every 1–2 minutes', min: 1, max: 2, response: 2 },
];
const field = 'mt-1 w-full rounded-lg border border-line bg-surface-2 px-3 py-2 text-sm';
export function SitePatrolSetup({ siteId, editable, latitude, longitude, localTest = false }: { siteId: string; editable: boolean; latitude?: number | null; longitude?: number | null; localTest?: boolean }) {
  const router = useRouter();
  const [policy, setPolicy] = useState<Policy>({ enabled: false, minIntervalMinutes: 15, maxIntervalMinutes: 40, responseMinutes: 10 });
  const [points, setPoints] = useState<Checkpoint[]>([]), [message, setMessage] = useState(''), [error, setError] = useState(''), [busy, setBusy] = useState(false), [formKey, setFormKey] = useState(0), [addPoint, setAddPoint] = useState(false);
  const [customTiming, setCustomTiming] = useState(false);
  const [printable, setPrintable] = useState<{ name: string; image: string } | null>(null);
  const load = useCallback(async () => { const r = await fetch(`/api/patrols/sites/${siteId}`); const d = await r.json(); if (!r.ok) throw Error(d.error); setPoints(d.checkpoints); if (d.patrolPolicy) setPolicy(d.patrolPolicy); }, [siteId]);
  useEffect(() => { load().catch(e => setError(e.message)); }, [load]);
  async function mutate(method: string, data: unknown) {
    setBusy(true); setMessage(''); setError('');
    try { const r = await fetch(`/api/patrols/sites/${siteId}`, { method, headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(data) }); const d = await r.json(); if (!r.ok) throw Error(d.error); await load(); router.refresh(); setMessage('Saved.'); return d; }
    catch (e) { setError(e instanceof Error ? e.message : 'Save failed'); return null; } finally { setBusy(false); }
  }
  async function sign(p: Checkpoint) {
    if(p.qrVersion < 2 && !window.confirm('Upgrade this checkpoint sign? The old paper sign will stop working. Download and mount the new sign, then sync the guard phone.')) return;
    setBusy(true); setError('');
    try {
      const r = await fetch(`/api/patrols/checkpoints/${p.id}/sign`, { method: p.qrVersion >= 2 ? 'GET' : 'POST' });
      const d = await r.json(); if(!r.ok) throw Error(d.error);
      setPrintable({name:d.name,image:d.qrImage}); await load();
      setMessage(p.qrVersion >= 2 ? 'Sign ready to download. Reprinting keeps the same checkpoint code.' : 'Sign upgraded. Replace the old paper sign and sync the guard phone.');
    } catch(e) { setError(e instanceof Error ? e.message : 'Unable to prepare sign'); } finally { setBusy(false); }
  }
  const active = points.filter(p => p.active);
  const available = presets.filter(p => p.id !== 'test' || localTest);
  const preset = customTiming ? 'custom' : available.find(p => p.min === policy.minIntervalMinutes && p.max === policy.maxIntervalMinutes && p.response === policy.responseMinutes)?.id ?? 'custom';
  return <Card><CardHeader title="QR checkpoints & patrol timing" description="Add the places the guard should visit. Download a QR sign for each place, then choose how often the phone prompts the guard." /><CardBody><div className="space-y-4">
    <ul className="divide-y divide-line">{active.map(p => <li key={p.id} className="flex flex-wrap items-center justify-between gap-2 py-3"><div><strong>{p.name}</strong><p className="text-xs text-ink-3">QR checkpoint · GPS checked within {p.radiusM} m</p></div>{editable && <Button size="sm" disabled={busy} onClick={() => sign(p)}>{p.qrVersion >= 2 ? 'Download QR sign' : 'Upgrade coordinate QR'}</Button>}{editable && <details className="text-xs"><summary className="cursor-pointer text-ink-3">Manage</summary><div className="mt-2 space-y-2"><p>{p.latitude.toFixed(5)}, {p.longitude.toFixed(5)}</p><Button size="sm" disabled={busy} onClick={() => mutate('DELETE', { checkpointId: p.id })}>Archive checkpoint</Button></div></details>}</li>)}</ul>
    {!active.length && <p className="text-sm text-ink-2">Start with one checkpoint, such as the main gate.</p>}
    {editable && <>
      {active.length > 0 && <Button onClick={() => setAddPoint(!addPoint)}>{addPoint ? 'Cancel adding checkpoint' : '+ Add another checkpoint'}</Button>}
      {(!active.length || addPoint) && <form key={formKey} className="space-y-4 rounded-xl border border-line p-4" onSubmit={async e => { e.preventDefault(); const fd = new FormData(e.currentTarget); if (!fd.get('latitude') || !fd.get('longitude')) { setError('Choose where this QR sign will be mounted on the map.'); return; } const d = await mutate('POST', { name: fd.get('name'), latitude: Number(fd.get('latitude')), longitude: Number(fd.get('longitude')), radiusM: Number(fd.get('radiusM')), priority: Number(fd.get('priority') ?? 1), minimumVisits: Number(fd.get('minimumVisits') ?? 1) }); if (d) { setPrintable({ name: d.checkpoint.name, image: d.qrImage }); setFormKey(k => k + 1); setAddPoint(false); setMessage('Checkpoint added. Download and print its QR sign below.'); } }}>
        <label className="block text-sm">Checkpoint name<input className={field} name="name" required maxLength={100} placeholder="e.g. Main gate" /></label>
        <div><h3 className="text-sm font-medium">Where will the QR sign be mounted?</h3><p className="mb-3 mt-1 text-xs text-ink-3">Move the pin to that place. The guard must scan nearby for GPS verification. Choose a radius of 50–100 m for a first test.</p><SitePicker names={{ lat: 'latitude', lng: 'longitude', radius: 'radiusM' }} initial={{ lat: latitude ?? null, lng: longitude ?? null, radiusM: 50 }} height={240} showSource={false} /></div>
        <details className="text-sm"><summary className="cursor-pointer text-ink-3">Advanced checkpoint options</summary><div className="mt-3 grid gap-3 sm:grid-cols-2"><label>Priority (1–10)<input className={field} type="number" name="priority" required min={1} max={10} defaultValue={1} /></label><label>Target visits per shift<input className={field} type="number" name="minimumVisits" required min={0} max={100} defaultValue={1} /></label></div></details>
        <Button disabled={busy} type="submit" variant="primary">{busy ? 'Saving…' : 'Create checkpoint & QR sign'}</Button>
      </form>}
      {printable && <div className="rounded-xl border border-ok/40 bg-ok-soft p-4"><p className="font-semibold">{printable.name} · QR sign ready</p><p className="mb-2 mt-1 text-sm text-ink-2">Mount this sign at its marked position. Its signed coordinates are checked against the phone’s GPS on every scan. A copy scanned elsewhere will fail the location check.</p><img src={printable.image} alt={`QR checkpoint ${printable.name}`} width={320} height={320} /><a href={printable.image} download={`crisis-${printable.name.replace(/[^a-z0-9]/gi, '-')}.png`} className="mt-3 inline-block rounded-lg bg-accent-gradient px-4 py-2 text-sm">Download QR sign</a></div>}
      <form className="space-y-4 border-t border-line pt-4" onSubmit={e => { e.preventDefault(); mutate('PUT', policy); }}>
        <label className="flex items-center gap-2 text-sm"><input type="checkbox" checked={policy.enabled} onChange={e => setPolicy({ ...policy, enabled: e.target.checked })} />Turn on patrols for this site</label>
        <label className="block text-sm">How often should the guard be prompted?<select aria-label="How often should the guard be prompted?" className={field} value={preset} onChange={e => { const p = available.find(p => p.id === e.target.value); setCustomTiming(!p); if (p) setPolicy({ ...policy, minIntervalMinutes: p.min, maxIntervalMinutes: p.max, responseMinutes: p.response }); }}>
          {available.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}<option value="custom">Custom timing</option>
        </select></label>
        {preset === 'custom' && <div className="grid gap-3 sm:grid-cols-3">{(['minIntervalMinutes', 'maxIntervalMinutes', 'responseMinutes'] as const).map((key, i) => <label key={key} className="text-sm">{['Minimum gap (min)', 'Maximum gap (min)', 'Time to respond (min)'][i]}<input type="number" className={field} value={policy[key]} min={1} max={key === 'responseMinutes' ? 60 : 240} required onChange={e => setPolicy({ ...policy, [key]: Number(e.target.value) })} /></label>)}</div>}
        <p className="text-xs text-ink-3">The exact prompt time varies within your chosen range. Updated timing applies when a guard next starts a patrol session.</p>
        <Button type="submit" disabled={busy || !active.length}>Save patrol timing</Button>
      </form>
    </>}
    <p role="alert" className="text-sm text-critical">{error}</p><p role="status" aria-live="polite" className="text-sm text-ok">{message}</p>
  </div></CardBody></Card>;
}
